def pixmap(nom, couleur="#3B3355", taille=20):
    """Retourne l'icone 'nom' sous forme d'image de la couleur voulue."""
    svg = SVG[nom].replace("currentColor", couleur)
    rendu = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    ratio = 2                                  # nette sur les ecrans HD
    pix = QPixmap(taille * ratio, taille * ratio)
    pix.fill(Qt.transparent)
    p = QPainter(pix)
    rendu.render(p, QRectF(0, 0, taille * ratio, taille * ratio))
    p.end()
    pix.setDevicePixelRatio(ratio)
    return pix


def icone(nom, couleur="#3B3355", taille=20, couleur_active=None):
    """QIcon pour un bouton (couleur_active : quand le bouton est coche)."""
    ic = QIcon()
    ic.addPixmap(pixmap(nom, couleur, taille), QIcon.Normal, QIcon.Off)
    if couleur_active:
        ic.addPixmap(pixmap(nom, couleur_active, taille), QIcon.Normal, QIcon.On)
    return ic
